const D = { energy:.6, scale:1, density:.5, speed:1, hue:36, x:.34, y:.62, side:'right', style:'limestone', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'engraving'), dk = (sty === 'chiaroscuro');
// a SET composites OVER a bg: alpha scales every mark. Never paint a black veil.
const AL = cl(P.alpha, 0, 100);
if (AL > 0.5) {

const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.24;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const BS = u*.60;                                     // bay pitch along the run, FIXED
const PW = BS*.30, PD = u*.34*P.scale;                // pier width along Z / arcade depth
const PH = u*.92*P.scale, SH = u*.50*P.scale;         // pier height / arch springing
const AT = u*.045*P.scale, CT = u*.055*P.scale, PL = u*.045*P.scale;
const NB = 3 + Math.round(cl(P.density,0,1)*4);
const DOFF = u*(.44 + .10*P.scale);

// the arcade holds still; the CAMERA breathes — a real parallax push, no beat flash
const camZ = -u*.30 + u*.095*dC*P.energy;
const camY = -(u*.34 + u*.030*dB*P.energy);
const yaw = .022*dA*P.energy;
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.05;
const vcx = cl(P.x,.08,.92)*width, vcy = cl(P.y,.3,.85)*height;

const side = P.side;
const camX = (side === 'both') ? u*.070*dA*P.energy : (side === 'left' ? DOFF : -DOFF) + u*.070*dA*P.energy;
const AXES = (side === 'both') ? [-DOFF, DOFF] : [0];

// the sun crawls: which pier faces catch it changes over minutes
const sunA = .85*Math.sin(K.t*.043*P.speed) + .34*Math.sin(K.t*.107*P.speed+2.0);
const sunZ = camZ + BS*(2.4 + 2.6*Math.sin(K.t*.061*P.speed) + 1.2*Math.sin(K.t*.139*P.speed+1.1));

const AXa = new Float64Array(40), AYa = new Float64Array(40), AZa = new Float64Array(40);
const BXa = new Float64Array(52), BYa = new Float64Array(52);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AXa[i] = X*ca - Z*sa; AYa[i] = Y; AZa[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZa[i], bz = AZa[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BXa[m] = vcx + f*AXa[i]/az; BYa[m] = vcy + f*AYa[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BXa[m] = vcx + f*(AXa[i]+(AXa[j]-AXa[i])*tt)/NEAR;
      BYa[m] = vcy + f*(AYa[i]+(AYa[j]-AYa[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BXa[i], BYa[i]); endShape(CLOSE);
  return true;
}

function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = paper ? [40, 6, 90] : wire ? [212, 58, 22] : dk ? [HU, 14, 8]
           : sty === 'terracotta' ? [16, 44, 32] : [(HU+2)%360, 20, 40];
const fogA = (paper||wire) ? .26 : .58;
function tone(v, tv){
  if (paper) return [40, 5 + 4*tv, cl(96 - 54*(1-v), 36, 96)];
  if (wire)  return [212, 60, cl(12 + 12*v, 8, 34)];
  if (dk)    return [HU, cl(24 - 13*v, 0, 28), cl(2 + 90*Math.pow(v,1.9), 1, 96)];
  if (sty === 'terracotta') return [cl(14 + 12*tv - 3*v, 2, 32), cl(52 - 18*v + 8*tv, 10, 66), cl(9 + 74*v, 5, 92)];
  return [cl(HU + 4 - 6*v + 6*tv, 0, 359), cl(24 - 12*v + 7*tv, 3, 34), cl(10 + 74*v, 5, 94)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a*AL/100);
  else if (paper) stroke(30, 20, 14, a*AL/100);
  else stroke((HU+2)%360, 12, 80, a*.28*AL/100);
}
function fl2(c, a){ fill(c[0], c[1], c[2], (a===undefined?100:a)*AL/100); }

const NA = 7;
strokeWeight(Math.max(1, u*.0015));

for (let ai2=0; ai2<AXES.length; ai2++){
  const ax = AXES[ai2];
  const dir = (ax - camX) >= 0 ? 1 : -1;          // the body extends AWAY from the camera
  const xF = ax, xB = ax + dir*PD;

  for (let k = NB-1; k >= 0; k--){                // far -> near
    const zP = k*BS, zN = (k+1)*BS;
    const hz = cl(k/NB, 0, 1);
    const tv = fr(k*31.7 + ai2*13.3);
    // raking light: the front face lights when the sun swings round to it
    const lamF = cl(.20 + .80*(dir > 0 ? -sunA : sunA) * .5 + .40, 0, 1);
    const lamZ = cl(.16 + .74*Math.exp(-Math.pow((zP - sunZ)/BS, 2)*.30), 0, 1);

    // ---- the spandrel: a wall with a semicircular hole punched from below
    const zL = zP + PW*.5, zR = zN - PW*.5, Zc = (zL+zR)*.5, R = (zR-zL)*.5;
    const wallV = (.24 + .40*lamF*(.5+.5*lamZ) + .08*tv) * (.5+.55*gl);
    let c = mixc(tone(cl(wallV,0,1), tv), HAZE, hz*fogA);
    const face = [];
    face.push(zL, -PH, 0); face.push(zR, -PH, 0);
    face.push(zR, -SH, 0);
    for (let i=0;i<=NA;i++){ const th = Math.PI*i/NA;
      face.push(Zc + R*Math.cos(th), -SH - R*Math.sin(th), 0); }
    face.push(zL, -SH, 0);
    const fv = [];
    for (let i=0;i<face.length;i+=3) fv.push(xF, face[i+1], face[i]);
    if (wire){ noFill(); ink(56); } else { noStroke(); fl2(c); }
    poly(fv);

    // ---- archivolt ring: a moulded band following the intrados
    for (let i=0;i<NA;i++){
      const t0 = Math.PI*i/NA, t1 = Math.PI*(i+1)/NA;
      const av = cl(wallV*(1.22 - .30*Math.abs(Math.cos((t0+t1)*.5))) + .06, 0, 1);
      const c2 = mixc(tone(av, tv), HAZE, hz*fogA);
      if (wire){ noFill(); ink(40); } else { noStroke(); fl2(c2); }
      poly([xF, -SH - R*Math.sin(t0), Zc + R*Math.cos(t0),
            xF, -SH - (R+AT)*Math.sin(t0), Zc + (R+AT)*Math.cos(t0),
            xF, -SH - (R+AT)*Math.sin(t1), Zc + (R+AT)*Math.cos(t1),
            xF, -SH - R*Math.sin(t1), Zc + R*Math.cos(t1)]);
    }
    // ---- the soffit: the barrel running back through the arch. This is the depth.
    for (let i=0;i<NA;i++){
      const t0 = Math.PI*i/NA, t1 = Math.PI*(i+1)/NA, tm = (t0+t1)*.5;
      const sv = cl((.07 + .30*Math.pow(Math.sin(tm), .8)*lamZ) * (.5+.55*gl), 0, 1);
      const c2 = mixc(tone(sv, tv), HAZE, hz*fogA*1.2);
      if (wire){ noFill(); ink(30); } else { noStroke(); fl2(c2); }
      poly([xF, -SH - R*Math.sin(t0), Zc + R*Math.cos(t0),
            xB, -SH - R*Math.sin(t0), Zc + R*Math.cos(t0),
            xB, -SH - R*Math.sin(t1), Zc + R*Math.cos(t1),
            xF, -SH - R*Math.sin(t1), Zc + R*Math.cos(t1)]);
    }

    // ---- pier: front face (ashlar-coursed, never a flat fill) + the return face
    const pv = (.22 + .44*lamF*(.5+.5*lamZ) + .08*tv) * (.5+.55*gl);
    for (let r=0; r<5; r++){
      const y0 = -PH + PH*(r/5), y1 = -PH + PH*((r+1)/5);
      const cv = cl(pv*(.88 + .22*fr(k*7.1 + r*3.3 + ai2*5.9)), 0, 1);
      const c2 = mixc(tone(cv, tv), HAZE, hz*fogA);
      if (wire){ noFill(); ink(52); } else { noStroke(); fl2(c2); }
      poly([xF, y0, zP - PW*.5, xF, y1, zP - PW*.5, xF, y1, zP + PW*.5, xF, y0, zP + PW*.5]);
    }
    const rv2 = cl((.09 + .16*lamZ) * (.5+.55*gl), 0, 1);
    const c3 = mixc(tone(rv2, tv), HAZE, hz*fogA);
    if (wire){ noFill(); ink(36); } else { noStroke(); fl2(c3); }
    poly([xF, -PH, zP - PW*.5, xB, -PH, zP - PW*.5, xB, 0, zP - PW*.5, xF, 0, zP - PW*.5]);
    ink(paper ? 34 : 26); noFill();
    poly([xF, -PH, zP - PW*.5, xF, 0, zP - PW*.5]);
  }

  // ---- cornice + plinth running the whole arcade
  const zA = -PW*.5, zB = NB*BS + PW*.5;
  for (let e=0;e<2;e++){
    const y0 = e ? -PL : -PH - CT, y1 = e ? 0 : -PH;
    const ev = cl(((e ? .13 : .40) + .26*(dir>0?-sunA:sunA)*.5) * (.5+.55*gl), 0, 1);
    const c = mixc(tone(ev, .5), HAZE, .3*fogA);
    if (wire){ noFill(); ink(58); } else { noStroke(); fl2(c); }
    poly([xF, y0, zA, xF, y1, zA, xF, y1, zB, xF, y0, zB]);
    const c2 = mixc(tone(cl(ev*1.5+.10,0,1), .5), HAZE, .3*fogA);   // the projecting drip
    if (!wire){ noStroke(); fl2(c2); }
    poly([xF, y0, zA, xF - dir*AT*.8, y0, zA, xF - dir*AT*.8, y0, zB, xF, y0, zB]);
  }

  // ---- light spilling through the openings (partial, ADD, low alpha)
  if (!paper && !wire && AL > 8){
    push(); blendMode(ADD); noStroke();
    for (let k=0;k<NB;k++){
      const zL = k*BS + PW*.5, zR = (k+1)*BS - PW*.5;
      const lz = cl(.20 + .80*Math.exp(-Math.pow((k*BS - sunZ)/BS, 2)*.34), 0, 1);
      fill(dk?HU:(HU+8)%360, dk?12:26, 100, cl((2.0 + 4.4*gl*lz)*AL/100, 0, 14));
      poly([xF, -SH*1.25, zL, xF, 0, zL, xF, 0, zR, xF, -SH*1.25, zR]);
    }
    pop(); blendMode(BLEND);
  }
}
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
}
